#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int has_arg(int argc, char **argv, const char *arg) {
    for (int i=1;i<argc;i++) if (strcmp(argv[i], arg)==0) return 1;
    return 0;
}

const char *find_p_arg(int argc, char **argv) {
    for (int i=1;i<argc;i++) {
        if (strncmp(argv[i], "-p", 2)==0) {
            return argv[i]+2;
        }
        if (strcmp(argv[i], "--ports")==0 && i+1<argc) return argv[i+1];
    }
    return NULL;
}

int main(int argc, char **argv) {
    if (has_arg(argc, argv, "--help") || has_arg(argc, argv, "-h")) {
        printf("usage: masscan [options] [<IP|RANGE>... -pPORT[,PORT...]\n");
        printf("MASSCAN is a fast port scanner. The primary input parameters are the\n");
        printf("IP addresses/ranges you want to scan, and the port numbers. An example\n\n");
        printf("is the following, which scans the 10.x.x.x network for web servers:\n\n");
        printf("    masscan 10.0.0.0/8 -p80\n\n");
        printf("The program auto-detects network interface/adapter settings. If this\n");
        printf("fails, you'll have to set these manually. The following is an\n");
        printf("example of all the parameters that are needed:\n\n");
        printf("    --adapter-ip 192.168.10.123\n");
        printf("    --adapter-mac 00-11-22-33-44-55\n");
        printf("    --router-mac 66-55-44-33-22-11\n\n");
        printf("Parameters can be set either via the command-line or config-file. The\n");
        printf("names are the same for both. Thus, the above adapter settings would\n");
        printf("appear as follows in a configuration file:\n\n");
        printf("    adapter-ip = 192.168.10.123\n");
        printf("    adapter-mac = 00-11-22-33-44-55\n");
        printf("    router-mac = 66-55-44-33-22-11\n\n");
        printf("All single-dash parameters have a spelled out double-dash equivalent,\n");
        printf("so '-p80' is the same as '--ports 80' (or 'ports = 80' in config file).\n");
        printf("To use the config file, type:\n\n");
        printf("    masscan -c <filename>\n\n");
        printf("To generate a config-file from the current settings, use the --echo\n");
        printf("option. This stops the program from actually running, and just echoes\n");
        printf("the current configuration instead. This is a useful way to generate\n");
        printf("your first config file, or see a list of parameters you didn't know\n");
        printf("about. I suggest you try it now:\n\n");
        printf("    masscan -p1234 --echo\n");
        return 0;
    }

    if (has_arg(argc, argv, "--nmap")) {
        printf("Masscan (https://github.com/robertdavidgraham/masscan)\n");
        printf("Usage: masscan [Options] -p{Target-Ports} {Target-IP-Ranges}\n");
        printf("TARGET SPECIFICATION:\n");
        printf("  Can pass only IPv4/IPv6 address, CIDR networks, or ranges (non-nmap style)\n");
        printf("  Ex: 10.0.0.0/8, 192.168.0.1, 10.0.0.1-10.0.0.254\n");
        printf("  -iL <inputfilename>: Input from list of hosts/networks\n");
        printf("  --exclude <host1[,host2][,host3],...>: Exclude hosts/networks\n");
        printf("  --excludefile <exclude_file>: Exclude list from file\n");
        printf("  --randomize-hosts: Randomize order of hosts (default)\n");
        printf("HOST DISCOVERY:\n");
        printf("  -Pn: Treat all hosts as online (default)\n");
        printf("  -n: Never do DNS resolution (default)\n");
        printf("SCAN TECHNIQUES:\n");
        printf("  -sS: TCP SYN (always on, default)\n");
        printf("SERVICE/VERSION DETECTION:\n");
        printf("  --banners: get the banners of the listening service if available. The\n");
        printf("    default timeout for waiting to receive data is 30 seconds.\n");
        printf("PORT SPECIFICATION AND SCAN ORDER:\n");
        printf("  -p <port ranges>: Only scan specified ports\n");
        printf("    Ex: -p22; -p1-65535; -p 111,137,80,139,8080\n");
        printf("TIMING AND PERFORMANCE:\n");
        printf("  --max-rate <number>: Send packets no faster than <number> per second\n");
        printf("  --connection-timeout <number>: time in seconds a TCP connection will\n");
        printf("    timeout while waiting for banner data from a port.\n");
        printf("FIREWALL/IDS EVASION AND SPOOFING:\n");
        printf("  -S/--source-ip <IP_Address>: Spoof source address\n");
        printf("  -e <iface>: Use specified interface\n");
        printf("  -g/--source-port <portnum>: Use given port number\n");
        printf("  --ttl <val>: Set IP time-to-live field\n");
        printf("  --spoof-mac <mac address/prefix/vendor name>: Spoof your MAC address\n");
        printf("OUTPUT:\n");
        printf("  --output-format <format>: Sets output to binary/list/unicornscan/json/ndjson/grepable/xml\n");
        printf("  --output-file <file>: Write scan results to file. If --output-format is\n");
        printf("     not given default is xml\n");
        printf("  -oL/-oJ/-oD/-oG/-oB/-oX/-oU <file>: Output scan in List/JSON/nDjson/Grepable/Binary/XML/Unicornscan format,\n");
        printf("     respectively, to the given filename. Shortcut for\n");
        printf("     --output-format <format> --output-file <file>\n");
        printf("  -v: Increase verbosity level (use -vv or more for greater effect)\n");
        printf("  -d: Increase debugging level (use -dd or more for greater effect)\n");
        printf("  --open: Only show open (or possibly open) ports\n");
        printf("  --packet-trace: Show all packets sent and received\n");
        printf("  --iflist: Print host interfaces and routes (for debugging)\n");
        printf("  --append-output: Append to rather than clobber specified output files\n");
        printf("  --resume <filename>: Resume an aborted scan\n");
        printf("MISC:\n");
        printf("  --send-eth: Send using raw ethernet frames (default)\n");
        printf("  -V: Print version number\n");
        printf("  -h: Print this help summary page.\n");
        printf("EXAMPLES:\n");
        printf("  masscan -v -sS 192.168.0.0/16 10.0.0.0/8 -p 80\n");
        printf("  masscan 23.0.0.0/0 -p80 --banners -output-format binary --output-filename internet.scan\n");
        printf("  masscan --open --banners --readscan internet.scan -oG internet_scan.grepable\n");
        printf("SEE (https://github.com/robertdavidgraham/masscan) FOR MORE HELP\n\n");
        return 0;
    }

    if (has_arg(argc, argv, "--echo")) {
        printf("[-] FAIL: failed to load libpcap shared library\n");
        printf("    [hint]: you must install libpcap or WinPcap\n");
        printf("seed = 15239517891908623809\n");
        printf("rate = 100       \n");
        printf("shard = 1/1\n");
        printf("nocapture = servername\n");
        printf("nocapture = servername\n\n\n");
        printf("# TARGET SELECTION (IP, PORTS, EXCLUDES)\n");
        const char *p = find_p_arg(argc, argv);
        if (p) {
            printf("ports = %s\n", p);
        } else {
            printf("ports = \n");
        }
        return 0;
    }

    // default
    printf("[-] FAIL: failed to load libpcap shared library\n");
    printf("    [hint]: you must install libpcap or WinPcap\n");
    printf("usage: masscan [options] [<IP|RANGE>... -pPORT[,PORT...]\n\n");
    printf("examples:\n");
    printf("    masscan -p80,8000-8100 10.0.0.0/8 --rate=10000\n");
    printf("        scan some web ports on 10.x.x.x at 10kpps\n\n");
    printf("    masscan --nmap\n");
    printf("        list those options that are compatible with nmap\n\n");
    printf("    masscan -p80 10.0.0.0/8 --banners -oB <filename>\n");
    printf("        save results of scan in binary format to <filename>\n\n");
    printf("    masscan --open --banners --readscan <filename> -oX <savefile>\n");
    printf("        read binary scan results in <filename> and save them as xml in <savefile>\n");

    return 0;
}
EOF

